import React, { useEffect, useInsertionEffect, useRef } from "react";
import { useState } from "react";
import { Scrollbar } from "react-scrollbars-custom";
import api from "../api/Webcall";
import { generateUUID, compressBase64, decompressBase64 } from "../utilities/utils";
import appsettings from "../../appsettings.json"


const UserBranchRoleList = () => {

  const [lstUserBranchRole, setUserBranchRole] = useState([]);
  const apiendpoints = appsettings.ApiEndpoints;

  const GetUserBranchRole = async () => {

    const convID = generateUUID();
    const frmHdr = { convid: convID, tag: "User Branch Role List", orgid: "", vendid: "0" };
    const frmData = {};
    const data = { hdr: frmHdr, body: frmData };
    const reqHdr = {};
    await api.post(apiendpoints.UserBranchRoleLst, compressBase64(data), reqHdr)
      .then(function (response) {
        const strResponse = JSON.parse(decompressBase64(response.data));
        setUserBranchRole(strResponse.body.Users);
      });
  }

  /*  Use Effect */
  useEffect(() => {
    GetUserBranchRole();
  }, []);

  return (
    <>
      <div className="row pad-top-0-5em pad-left-15">

        <table className="lst-grid">

          <thead>
            <tr>
              <th className="text-center">User Id</th>
              <th className="text-center">User Name</th>
              <th className="text-center">Branch Id</th>
              <th className="text-center">Branch Name</th>
              <th className="text-center">Role Id</th>
              <th className="text-center">Role Name</th>
            </tr>
          </thead>

          <tbody>
            {lstUserBranchRole &&
              lstUserBranchRole.map((x) => {
                return (
                  <tr>
                    <td>{x.UserId}</td>
                    <td>{x.UserName}</td>
                    <td>{x.BranchId}</td>
                    <td>{x.BranchName}</td>
                    <td>{x.RoleId}</td>
                    <td>{x.RoleName}</td>
                  </tr>
                );
              })}
          </tbody>
        </table>

      </div>

    </>
  );
};

export default UserBranchRoleList;
